import re,os
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
m=re.search(r'Test input \((\d+)x(\d+)\):\n',t)
h,w=int(m[1]),int(m[2])
G=[[int(x) for x in r.split()] for r in t[m.end():].split('\n')[:h]]
print(h,w)
# vertical mirror pairs
pairs={}
for i in range(h):
    for j in range(h):
        if G[i]==G[j]: pairs.setdefault(i,set()).add(j)
for i in range(h): print(i,sorted(pairs.get(i,[])))

# check column mirror symmetry of G (ignoring 8s)
def eq_ignoring(a,b,ig={8}):
    return all(x==y or x in ig or y in ig for x,y in zip(a,b))
cols=[ [G[i][j] for i in range(30)] for j in range(30)]
for j in range(30):
    m=[29-j] if eq_ignoring(cols[j],cols[29-j]) else None
    if m: pass
print(all(eq_ignoring(cols[j],cols[29-j]) for j in range(15)))
# rotation?
print(all(eq_ignoring(G[i],G[29-i][::-1]) for i in range(30)))

